RED.contextMenu = (function () {

    let menu;

    function disposeMenu() {
        $(document).off("mousedown.red-ui-workspace-context-menu");
        if (menu) {
            menu.remove();
        }
        menu = null;
    }
    function show(options) {
        
        if (menu) {
            menu.remove()
        }
        let menuItems = []
        if (options.options) {
            menuItems = options.options
        } else if (options.type === 'workspace') {
            const selection = RED.view.selection()
            const noSelection = !selection || Object.keys(selection).length === 0
            const hasSelection = (selection.nodes && selection.nodes.length > 0);
            const hasMultipleSelection = hasSelection && selection.nodes.length > 1;
            const virtulLinks = (selection.links && selection.links.filter(e => !!e.link)) || [];
            const wireLinks = (selection.links && selection.links.filter(e => !e.link)) || [];
            const hasLinks = wireLinks.length > 0;
            const isSingleLink = !hasSelection && hasLinks && wireLinks.length === 1
            const isMultipleLinks = !hasSelection && hasLinks && wireLinks.length > 1
            const canDelete = hasSelection || hasLinks
            const isGroup = hasSelection && selection.nodes.length === 1 && selection.nodes[0].type === 'group'
            const canEdit = !RED.workspaces.isLocked()
            const canRemoveFromGroup = hasSelection && !!selection.nodes[0].g
            let hasGroup, isAllGroups = true, hasDisabledNode, hasEnabledNode, hasLabeledNode, hasUnlabeledNode;
            if (hasSelection) {
                const nodes = selection.nodes.slice();
                while (nodes.length) {
                    const n = nodes.shift();
                    if (n.type === 'group') {
                        hasGroup = true;
                        nodes.push(...n.nodes);
                    } else {
                        isAllGroups = false;
                        if (n.d) {
                            hasDisabledNode = true;
                        } else {
                            hasEnabledNode = true;
                        }
                    }
                    if (n.l === undefined) {
                        // Check if the node sets showLabel in the defaults
                        // as that determines the default behaviour for the node
                        if (n._def.showLabel !== false) {
                            hasLabeledNode = true;
                        } else {
                            hasUnlabeledNode = true;
                        }
                    } else {
                        if (n.l) {
                            hasLabeledNode = true;
                        } else {
                            hasUnlabeledNode = true;
                        }
                    }
                }
            }

            const scale = RED.view.scale()
            const offset = $("#red-ui-workspace-chart").offset()
            let addX = (options.x - offset.left + $("#red-ui-workspace-chart").scrollLeft()) / scale
            let addY = (options.y - offset.top + $("#red-ui-workspace-chart").scrollTop()) / scale

            if (RED.view.snapGrid) {
                const gridSize = RED.view.gridSize()
                addX = gridSize * Math.round(addX / gridSize)
                addY = gridSize * Math.round(addY / gridSize)
            }



            if (RED.settings.theme("menu.menu-item-action-list", true)) {
                menuItems.push(
                    { onselect: 'core:show-action-list', label: RED._("contextMenu.showActionList"), onpostselect: function () { } }
                )
            }
            
            // Flatten the insert options directly into the main menu for better UX
            const nodeHandler = function () {
                try {
                    if (typeof RED.view.showQuickAddDialog === 'function') {
                        RED.view.showQuickAddDialog({
                            position: [addX, addY],
                            touchTrigger: 'ontouchstart' in window,
                            splice: isSingleLink ? selection.links[0] : undefined,
                        });
                    }
                } catch(err) {
                    console.error("Error in context menu Insert Node:", err);
                }
            };
            
            // Add insert options directly to main menu
            menuItems.push(
                {
                    label: "Insert Node",
                    onselect: nodeHandler,
                    disabled: !canEdit
                },
                (hasLinks) ? { // has least 1 wire selected
                    label: "Insert Junction",
                    onselect: function () {
                        RED.actions.invoke('core:split-wires-with-junctions', { x: addX, y: addY })
                    },
                    disabled: !canEdit || !hasLinks
                } : {
                    label: "Insert Junction",
                    onselect: function () {
                        const nn = {
                            _def: { defaults: {} },
                            type: 'junction',
                            z: RED.workspaces.active(),
                            id: RED.nodes.id(),
                            x: addX,
                            y: addY,
                            w: 0, h: 0,
                            outputs: 1,
                            inputs: 1,
                            dirty: true,
                            moved: true
                        }
                        const junction = RED.nodes.addJunction(nn);
                        const historyEvent = {
                            dirty: RED.nodes.dirty(),
                            t: 'add',
                            junctions: [junction]
                        }
                        RED.history.push(historyEvent);
                        RED.nodes.dirty(true);
                        RED.view.select({nodes: [junction] });
                        RED.view.redraw(true)
                    },
                    disabled: !canEdit
                }
            );
            
            if (hasLinks) {
                menuItems.push({
                    label: "Insert Link Nodes",
                    onselect: 'core:split-wire-with-link-nodes',
                    disabled: !canEdit || !hasLinks
                });
            }
            
            if (RED.settings.theme("menu.menu-item-import-library", true)) {
                menuItems.push(
                    { onselect: 'core:show-import-dialog', label: RED._('common.label.import')},
                    { onselect: 'core:show-examples-import-dialog', label: RED._('menu.label.importExample') }
                )
            }


            if (hasSelection && canEdit) {
                // Flatten node options directly into main menu
                if (!hasMultipleSelection && !isGroup) {
                    menuItems.push(
                        { onselect: 'core:show-node-help', label: RED._('menu.label.showNodeHelp') }
                    );
                }
                
                // Add node control options
                menuItems.push(
                    { onselect: 'core:enable-selected-nodes', label: "Enable Selected Nodes", disabled: !hasDisabledNode },
                    { onselect: 'core:disable-selected-nodes', label: "Disable Selected Nodes", disabled: !hasEnabledNode }
                );
                
                // Add label options
                menuItems.push(
                    { onselect: 'core:show-selected-node-labels', label: "Show Node Labels", disabled: !hasUnlabeledNode },
                    { onselect: 'core:hide-selected-node-labels', label: "Hide Node Labels", disabled: !hasLabeledNode }
                );
                
                // Flatten group options directly into main menu  
                menuItems.push(
                    { onselect: 'core:group-selection', label: "Group Selection" },
                    { onselect: 'core:ungroup-selection', label: "Ungroup Selection", disabled: !hasGroup }
                );
                
                if (hasGroup) {
                    menuItems.push(
                        { onselect: 'core:merge-selection-to-group', label: "Merge to Group" }
                    );
                }
                
                if (canRemoveFromGroup) {
                    menuItems.push(
                        { onselect: 'core:remove-selection-from-group', label: "Remove from Group" }
                    );
                }
                
                menuItems.push(
                    { onselect: 'core:copy-group-style', label: "Copy Group Style", disabled: !hasGroup },
                    { onselect: 'core:paste-group-style', label: "Paste Group Style", disabled: !hasGroup}
                );
            }
            
            if (canEdit && hasMultipleSelection) {
                // Flatten arrange options directly into main menu
                menuItems.push(
                    { label: "Align Left", onselect: "core:align-selection-to-left"},
                    { label: "Align Center", onselect: "core:align-selection-to-center"},
                    { label: "Align Right", onselect: "core:align-selection-to-right"},
                    { label: "Align Top", onselect: "core:align-selection-to-top"},
                    { label: "Align Middle", onselect: "core:align-selection-to-middle"},
                    { label: "Align Bottom", onselect: "core:align-selection-to-bottom"},
                    { label: "Distribute Horizontally", onselect: "core:distribute-selection-horizontally"},
                    { label: "Distribute Vertically", onselect: "core:distribute-selection-vertically"}
                );
            }


            menuItems.push(
                null,
                { onselect: 'core:undo', label: RED._("keyboard.undoChange"), disabled: RED.history.list().length === 0 },
                { onselect: 'core:redo', label: RED._("keyboard.redoChange"), disabled: RED.history.listRedo().length === 0 },
                null,
                { onselect: 'core:cut-selection-to-internal-clipboard', label: RED._("keyboard.cutNode"), disabled: !canEdit || !hasSelection },
                { onselect: 'core:copy-selection-to-internal-clipboard', label: RED._("keyboard.copyNode"), disabled: !hasSelection },
                { onselect: 'core:paste-from-internal-clipboard', label: RED._("keyboard.pasteNode"), disabled: !canEdit || !RED.view.clipboard() },
                { onselect: 'core:delete-selection', label: RED._('keyboard.deleteSelected'), disabled: !canEdit || !canDelete },
                { onselect: 'core:delete-selection-and-reconnect', label: RED._('keyboard.deleteReconnect'), disabled: !canEdit || !canDelete },
            )
            if (RED.settings.theme("menu.menu-item-export-library", true)) {
                menuItems.push(
                    { onselect: 'core:show-export-dialog', label: RED._("menu.label.export") }
                )
            }
            menuItems.push(
                { onselect: 'core:select-all-nodes', label: RED._("keyboard.selectAll") }
            )
        }

        var direction = "right";
        var MENU_WIDTH = 500; // can not use menu width here
        if ((options.x -$(document).scrollLeft()) >
            ($(window).width() -MENU_WIDTH)) {
            direction = "left";
        }


        
        menu = RED.menu.init({
            direction: direction,
            onpreselect: function() {
                disposeMenu()
            },
            onpostselect: function () {
                RED.view.focus()
            },
            options: menuItems
        });

        menu.attr("id", "red-ui-workspace-context-menu");
        menu.css({
            position: "absolute",
            zIndex: 10001  // Ensure menu is above other elements
        })
        menu.appendTo("body");

        // Improved positioning to prevent overflow
        var menuWidth = menu.outerWidth() || 200;  // fallback width
        var menuHeight = menu.outerHeight() || 200; // fallback height
        var windowWidth = $(window).width();
        var windowHeight = $(window).height();
        var scrollTop = $(document).scrollTop();
        var scrollLeft = $(document).scrollLeft();

        var top = options.y
        var left = options.x

        // Adjust for bottom overflow
        if (top + menuHeight - scrollTop > windowHeight) {
            top = Math.max(scrollTop + 10, top - menuHeight);
        }
        
        // Adjust for right overflow  
        if (left + menuWidth - scrollLeft > windowWidth) {
            left = Math.max(scrollLeft + 10, left - menuWidth);
        }

        // Ensure menu doesn't go off screen top/left
        if (top < scrollTop + 10) {
            top = scrollTop + 10;
        }
        if (left < scrollLeft + 10) {
            left = scrollLeft + 10;
        }

        menu.css({
            top: top + "px",
            left: left + "px"
        })
        $(".red-ui-menu.red-ui-menu-dropdown").hide();
        $(document).on("mousedown.red-ui-workspace-context-menu", function (evt) {
            if (menu && menu[0].contains(evt.target)) {
                return
            }
            disposeMenu()
        });
        menu.show();
        
        // set focus to first item so that pressing escape key closes the menu
        $("#red-ui-workspace-context-menu :first(ul) > a").trigger("focus")

    }
    // Allow escape key hook and other editor events to close context menu
    RED.keyboard.add("red-ui-workspace-context-menu", "escape", function () { RED.contextMenu.hide() })
    RED.events.on("editor:open", function () { RED.contextMenu.hide() });
    RED.events.on("search:open", function () { RED.contextMenu.hide() });
    RED.events.on("type-search:open", function () { RED.contextMenu.hide() });
    RED.events.on("actionList:open", function () { RED.contextMenu.hide() });
    RED.events.on("view:selection-changed", function () { RED.contextMenu.hide() });
    return {
        show: show,
        hide: disposeMenu
    }
})()
